<template><AppLayout page-title="Détail de la commande"><div v-if="loading" class="loading-overlay"><div class="spinner"/></div><div v-else-if="order" class="grid-2"><section class="card"><h2>{{order.order_number}}</h2><p>Statut : <span class="badge">{{order.status}}</span></p><p>Paiement : {{order.payment_status}}</p><p>Mode : {{order.delivery_mode}}</p><p v-if="order.delivery_address">{{order.delivery_address}}, {{order.delivery_city}}</p><div class="total">À payer : <b>{{Number(order.patient_amount).toLocaleString('fr-FR')}} {{order.currency}}</b></div></section><section class="card"><h3>Pharmacies</h3><div v-for="f in fulfillments" :key="f.id" class="prescription"><b>{{f.pharmacy?.name}}</b><span class="badge">{{f.status}}</span><ul><li v-for="i in f.order_items" :key="i.id">{{i.product_name}} × {{i.quantity}} — {{Number(i.total_price).toLocaleString('fr-FR')}} XOF</li></ul></div></section></div></AppLayout></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import AppLayout from '@/components/layout/AppLayout.vue';import {supabase} from '@/lib/supabase';const route=useRoute(),order=ref<any>(),fulfillments=ref<any[]>([]),loading=ref(true);onMounted(async()=>{const id=String(route.params.id);const {data}=await supabase.from('orders').select('*').eq('id',id).single();order.value=data;const {data:f}=await supabase.from('order_fulfillments').select('*,pharmacy:pharmacies(name),order_items(*)').eq('order_id',id);fulfillments.value=f||[];loading.value=false})</script>
